-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset($data$[{"queue_id": "337a4d4a-1267-48e6-a483-9e4ff8b679c8", "shop": "beou", "listing_id": "1341529845", "source_url": "https://www.etsy.com/listing/1341529845/farmhouse-sheer-pull-up-curtain-custom", "category": "Tie-Up & Balloon Shades", "image_url": null, "destination_url": "https://www.etsy.com/listing/1341529845/farmhouse-sheer-pull-up-curtain-custom", "title": "Farmhouse Sheer Pull-Up Curtain: Custom Tie-Up Kitchen & Living Room", "body": "Farmhouse Sheer Pull-Up Curtain: Custom Tie-Up Kitchen & Living Room Style: farmhouse, rustic. Materials: blended. View details and available options on Etsy.", "handle": "icyndizhang", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/31778838/r/il/06c57d/5103441447/il_794xN.5103441447_ridz.jpg", "new_title": "Soft Sheer Tie-Up Curtain Panel", "new_body": "Soft folds and adjustable ties create a relaxed farmhouse window detail. This blended-fabric curtain from beou is sold as one panel, with custom sizes offered in the original listing.", "facebook_draft": "Bring soft folds to a kitchen or living-room window with this beou tie-up curtain. One panel per order; check the shop for available sizes. https://www.etsy.com/listing/1341529845/farmhouse-sheer-pull-up-curtain-custom", "board_id": "801218658646993070", "checked_at": "2026-10-18T02:08:56.248708+00:00", "visual_verified": true, "available": true}, {"queue_id": "abadadaf-57d3-4c91-9c7e-428c0356373e", "shop": "LambertHouse", "listing_id": "1787372056", "source_url": "https://www.etsy.com/listing/1787372056/510-pcs-premium-gold-aluminum-coat", "category": "Closet Organization", "image_url": null, "destination_url": "https://www.etsy.com/listing/1787372056/510-pcs-premium-gold-aluminum-coat", "title": "Gold Aluminum Alloy Clothes Hangers, Premium Metal Suit Hangers", "body": "Gold Aluminum Alloy Clothes Hangers, Premium Metal Suit Hangers Style: modern, luxury. Materials: aluminum. View details and available options on Etsy.", "handle": "sailing_981", "mapped": true, "history_count": 0, "review_exists": false, "new_image_url": "https://i.etsystatic.com/46944744/r/il/e1b287/6362532043/il_794xN.6362532043_syvu.jpg", "new_title": "Gold-Toned Metal Clothes Hangers", "new_body": "Gold-toned metal hangers with shaped shoulders and a lower bar bring a coordinated look to a closet. LambertHouse offers sets of 5 or 10; explore the original listing for color options.", "facebook_draft": "A coordinated closet detail: gold-toned metal hangers from LambertHouse, offered in 5- or 10-piece sets. View the available finishes in the shop. https://www.etsy.com/listing/1787372056/510-pcs-premium-gold-aluminum-coat", "board_id": "863494997243989843", "checked_at": "2026-10-18T02:08:56.248769+00:00", "visual_verified": true, "available": true}]$data$::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text,facebook_draft text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status='draft' and cv.status='draft' and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id)
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 2 then raise exception 'Expected 2 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;

update products p set primary_image_url=x.new_image_url,original_image_urls=jsonb_build_array(x.new_image_url),source_payload=coalesce(p.source_payload,'{}'::jsonb)||jsonb_build_object('material_verification',jsonb_build_object('source_url',x.source_url,'verified_at',x.checked_at,'image_verified',true,'batch','daily-20261018-b2')) from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set image_url=x.new_image_url,title=x.new_title,body=x.facebook_draft
from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.product_id=q.product_id and cv.shop_id=q.shop_id and cv.platform='facebook' and cv.status='draft'
and not exists(select 1 from publish_history h where h.content_variant_id=cv.id)
and not exists(select 1 from publish_queue fq where fq.content_variant_id=cv.id and fq.status<>'draft');

insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;

create temporary table batch_input as select * from jsonb_to_recordset($data$[{"shop": "NngGoods", "handle": "ivy5205", "listing_id": "4571804678", "source_url": "https://www.etsy.com/listing/4571804678/natural-amethyst-cabinet-knob-double", "category": "Cabinet Knobs & Pulls", "board_id": "713820678377803412", "new_title": "Double-Point Stone Cabinet Knobs", "body": "Faceted stone points on brass bases add a distinctive accent to drawers and cabinets. NngGoods offers several stone options. Natural color and pattern vary; see Etsy for selection and fitting details.", "image_url": "https://i.etsystatic.com/57194200/r/il/134c10/8715841347/il_794xN.8715841347_5m5f.jpg", "checked_at": "2026-10-18T02:08:56.248772+00:00", "facebook_draft": "Give a dresser a small refresh with double-point stone cabinet knobs from NngGoods. Natural stone patterns vary. Explore the available options: https://www.etsy.com/listing/4571804678/natural-amethyst-cabinet-knob-double", "available": true, "visual_verified": true}, {"shop": "NngGoods", "handle": "ivy5205", "listing_id": "4582976030", "source_url": "https://www.etsy.com/listing/4582976030/natural-stone-cabinet-knob-brass-drawer", "category": "Cabinet Knobs & Pulls", "board_id": "713820678377803412", "new_title": "Oval Stone and Brass Cabinet Knobs", "body": "Smooth oval stone tops meet brass bases in these NngGoods furniture knobs. Choose from the stone options in the original Etsy listing. Each stone has its own color and markings.", "image_url": "https://i.etsystatic.com/57194200/r/il/f9c54d/8663653356/il_794xN.8663653356_kdse.jpg", "checked_at": "2026-10-18T02:08:56.248774+00:00", "facebook_draft": "Give a dresser a small refresh with oval stone and brass cabinet knobs from NngGoods. Natural stone patterns vary. Explore the available options: https://www.etsy.com/listing/4582976030/natural-stone-cabinet-knob-brass-drawer", "available": true, "visual_verified": true}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text,handle text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle=x.handle and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)=x.handle)<>2 then raise exception 'Batch routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','daily-20261018-b2'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261016',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261016',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle=x.handle and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
